var FA_MAP = {"0":"۰","1":"۱","2":"۲","3":"۳","4":"۴","5":"۵","6":"۶","7":"۷","8":"۸","9":"۹"};
function faNum(n){ return String(n).replace(/[0-9]/g, function(d){return FA_MAP[d];}); }

var listEl = document.getElementById('crimeList');
var emptyEl = document.getElementById('crimeEmpty');
var countEl = document.getElementById('resultCount');
var activeCat = '';

function render(items){
  listEl.innerHTML = '';
  if(items.length === 0){
    emptyEl.style.display = 'block';
    countEl.textContent = '';
    return;
  }
  emptyEl.style.display = 'none';
  countEl.textContent = faNum(items.length) + ' نتیجه';
  items.forEach(function(item){
    var row = document.createElement('a');
    row.className = 'crime-row';
    row.href = '/laws/' + item.n + '/';
    row.innerHTML = '<div class="law-num">' + faNum(item.n) + '</div><div class="crime-title">' + item.t + '</div><svg><use href="#i-arrow" style="transform:rotate(180deg)"/></svg>';
    listEl.appendChild(row);
  });
}

function doSearch(){
  var q = document.getElementById('crimeSearch').value.trim();
  var matchArticleNum = q.match(/(\d+)/);
  var results = CRIMES.filter(function(item){
    var inCat = activeCat === '' || item.c.some(function(c){ return CATS[activeCat] === c; });
    if(!inCat) return false;
    if(!q) return true;
    if(matchArticleNum && String(item.n) === matchArticleNum[1]) return true;
    return item.t.indexOf(q) !== -1;
  });
  render(results);
}

var CATS = ["حدود و تعزیر عمومی","اخلاق و مذهب","خانواده و اقارب","اموال، دزدی و مالی","اسناد و جعل","مواد غذایی و دوایی","اسلحه","مواد مخدر","ادارۀ دولتی و رشوت"];

document.getElementById('crimeSearchBtn').addEventListener('click', doSearch);
document.getElementById('crimeSearch').addEventListener('input', doSearch);
document.getElementById('crimeSearch').addEventListener('keydown', function(e){ if(e.key === 'Enter') doSearch(); });

document.querySelectorAll('#catChips button').forEach(function(btn){
  btn.addEventListener('click', function(){
    document.querySelectorAll('#catChips button').forEach(function(b){ b.classList.remove('active'); });
    btn.classList.add('active');
    activeCat = btn.dataset.cat;
    doSearch();
  });
});

// support ?cat=<index> deep link from the landing page category cards
var params = new URLSearchParams(window.location.search);
var catParam = params.get('cat');
if(catParam !== null && document.querySelector('#catChips button[data-cat="'+catParam+'"]')){
  document.querySelectorAll('#catChips button').forEach(function(b){ b.classList.remove('active'); });
  var b = document.querySelector('#catChips button[data-cat="'+catParam+'"]');
  b.classList.add('active');
  activeCat = catParam;
}

render(CRIMES.filter(function(item){
  return activeCat === '' || item.c.some(function(c){ return CATS[activeCat] === c; });
}));
